using Acme.Data;
using Acme.Notifications;
using Microsoft.EntityFrameworkCore;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<AppDbContext>(o => o.UseNpgsql(builder.Configuration.GetConnectionString("App")));
builder.Services.AddAuthentication().AddJwtBearer();
builder.Services.AddAuthorization();
builder.Services.AddSignalR();
builder.Services.AddScoped<ProjectNotifier>();

var app = builder.Build();
app.UseAuthentication();
app.UseAuthorization();

app.MapHub<NotificationHub>("/hubs/notifications");

app.Run();

using Microsoft.AspNetCore.SignalR;

namespace Acme.Notifications;

public sealed class NotificationHub : Hub
{
}

using Microsoft.AspNetCore.SignalR;

namespace Acme.Notifications;

public sealed class ProjectNotifier(IHubContext<NotificationHub> hub)
{
    public Task TaskUpdatedAsync(int projectId, TaskSummary task, CancellationToken ct) =>
        hub.Clients.All.SendAsync("TaskUpdated", task, ct);
}

public sealed record TaskSummary(int Id, string Title, string AssigneeEmail);

namespace Acme.Data;

public enum MemberRole { Owner, Member, Guest }

public sealed class ProjectMember
{
    public int ProjectId { get; set; }
    public string UserId { get; set; } = "";
    public MemberRole Role { get; set; }
}

