using Acme.Data;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.SignalR;
using Microsoft.EntityFrameworkCore;

namespace Acme.Notifications;

[Authorize]
public sealed class NotificationHub(AppDbContext db) : Hub
{
    public static string ProjectGroup(int projectId) => $"project:{projectId}";

    public override async Task OnConnectedAsync()
    {
        var userId = Context.UserIdentifier!;
        var projectIds = await db.ProjectMembers
            .Where(m => m.UserId == userId)
            .Select(m => m.ProjectId)
            .ToListAsync(Context.ConnectionAborted);

        foreach (var projectId in projectIds)
        {
            await Groups.AddToGroupAsync(Context.ConnectionId, ProjectGroup(projectId), Context.ConnectionAborted);
        }

        await base.OnConnectedAsync();
    }
}
